import { useState } from 'react';
import { Switch } from '../components/Switch';
import { Button } from '../components/Button';
import './notification-settings.css';

export function NotificationSettings() {
  const [emailEnabled, setEmailEnabled] = useState(true);
  const [pushEnabled, setPushEnabled] = useState(true);
  const [saved, setSaved] = useState(false);

  const handleSave = () => {
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
  };

  return (
    <div className="notification-settings">
      <div className="notification-settings__container">
        <h1 className="notification-settings__title">Notification Settings</h1>

        <div className="notification-settings__content">
          <div className="notification-settings__option">
            <Switch
              checked={emailEnabled}
              label="Email Notifications"
              onChange={(e) => setEmailEnabled(e.target.checked)}
            />
          </div>

          <div className="notification-settings__option">
            <Switch
              checked={pushEnabled}
              label="Push Notifications"
              onChange={(e) => setPushEnabled(e.target.checked)}
            />
          </div>
        </div>

        <div className="notification-settings__footer">
          <Button Label="Save" onClick={handleSave} />
          {saved && <span className="notification-settings__confirmation">✓ Saved</span>}
        </div>
      </div>
    </div>
  );
}

