import React, { useState } from 'react';
import './search-header.css';

export default function SearchHeader() {
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState('today');

  const filters = [
    { id: 'today', label: 'Today', isNew: true },
    { id: 'week', label: 'This week', isNew: false },
    { id: 'month', label: 'This month', isNew: false },
  ];

  const handleSearch = () => {
    console.log('Search:', searchQuery, 'Filter:', activeFilter);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <div className="search-header">
      <div className="search-container">
        <div className="search-input-group">
          <input
            type="text"
            className="search-input"
            placeholder="Search results..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={handleKeyPress}
            aria-label="Search query"
          />
          <button
            className="search-button"
            onClick={handleSearch}
            aria-label="Submit search"
          >
            Search
          </button>
        </div>

        <div className="filters-group">
          {filters.map((filter) => (
            <div key={filter.id} className="filter-chip-wrapper">
              <button
                className={`filter-chip ${activeFilter === filter.id ? 'active' : ''}`}
                onClick={() => setActiveFilter(filter.id)}
                aria-pressed={activeFilter === filter.id}
              >
                {filter.label}
              </button>
              {filter.isNew && <span className="new-label">New</span>}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

