import { useState } from 'react';
import { Field } from './Field';
import { Chip } from './Chip';
import { Button } from './Button';
import { Tag } from './Tag';
import './search-results-header.css';

export function SearchResultsHeader({ onSearch }) {
  const [searchQuery, setSearchQuery] = useState('');
  const [activeFilter, setActiveFilter] = useState('today');

  const filters = [
    { id: 'today', label: 'Today', isNew: true },
    { id: 'week', label: 'This week' },
    { id: 'month', label: 'This month' },
  ];

  const handleSearch = () => {
    if (onSearch) {
      onSearch({ query: searchQuery, filter: activeFilter });
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <div className="search-results-header">
      <div className="search-results-header__input-row">
        <Field
          label="Search"
          placeholder="Enter search terms..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          className="search-results-header__field"
        />
        <Button Label="Search" onClick={handleSearch} className="search-results-header__button" />
      </div>

      <div className="search-results-header__filters">
        {filters.map((filter) => (
          <div key={filter.id} className="search-results-header__filter-item">
            <Chip
              Label={filter.label}
              Size="L"
              pressed={activeFilter === filter.id}
              onClick={() => setActiveFilter(filter.id)}
              className={`search-results-header__chip ${activeFilter === filter.id ? 'search-results-header__chip--active' : ''}`}
            />
            {filter.isNew && <Tag Label="New" Tone="Neutral" className="search-results-header__tag" />}
          </div>
        ))}
      </div>
    </div>
  );
}

